config.script:
	# if event.enabled:
		# add your action handling code
	#----File Menu Items------------------------------------------------------------
	if event.label=='New':
		view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/EmbeddedViews/NewPopup'
		system.perspective.openPopup('saveNew', view, title='Save?', params={'lastLoad': self.view.params.lastLoad})

	elif event.label=='Open':
		system.perspective.sendMessage('cancelConfigs', True, scope='session')
		if self.session.custom.saveToMongo:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/LoadArchitectureFromMongo'
		else:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/LoadArchitectureFromFileSystem'

		system.perspective.openPopup('insertArch', view, title='Open Architecture', params={'load': True})

	elif event.label=='Insert':
		system.perspective.sendMessage('cancelConfigs', True, scope='session')
		if self.session.custom.saveToMongo:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/LoadArchitectureFromMongo'
		else:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/LoadArchitectureFromFileSystem'
		system.perspective.openPopup('insertArch', view, title='Insert Architecture', params={'load': False})

	elif event.label in ['Save...','Save As...']and (not self.session.custom.admin.savingDisabled):
		system.perspective.sendMessage('cancelConfigs', True, scope='session')
		if self.session.custom.saveToMongo:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/SaveArchitectureToMongo'
		else:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/SaveArchitectureToFileSystem'
		system.perspective.openPopup('saveArchitecture', view, params={'lastLoad': self.view.params.lastLoad}, title="Save Architecture")		

	elif event.label=='Manage Files' and (not self.session.custom.admin.deletingDisabled):
		system.perspective.sendMessage('cancelConfigs', True, scope='session')
		if self.session.custom.saveToMongo:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/FileManagerMongo'
		else:
			view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/FileManagerFileSystem'
		system.perspective.openPopup('manageFiles', view, title='Manage Files', params={'load': True})

	elif event.label=='Print':
		system.perspective.sendMessage('Print', True, scope='session')

	elif event.label=='Export':
		#system.perspective.sendMessage('downloadLayout', True, scope='session')
		system.perspective.openPopup("Export", "Exchange/ArchitectureBuilder/BOM/Popups/Export", title="Download", )

	elif event.label=='Import':
		system.perspective.sendMessage('cancelConfigs', True, scope='session')
		view='Exchange/ArchitectureBuilder/EmbeddedViewsMain/UploadArchitecture'
		system.perspective.openPopup('uploadArch', view, title='Upload Architecture')

	#----BOM Menu Items------------------------------------------------------------
	elif event.label=='Clear':
		self.getSibling("ArchitectureBuilder").props.nodes={}
		self.getSibling("ArchitectureBuilder").props.edges={}

	elif event.label=='Decrease Snap (-5)':
		self.getSibling("ArchitectureBuilder").props.snapPixels-=5

	elif event.label=='Increase Snap (+5)':
		self.getSibling("ArchitectureBuilder").props.snapPixels+=5

	elif event.label=='Disable Snap':
		self.getSibling("ArchitectureBuilder").props.snapEnabled=False

	elif event.label=='Enable Snap':
		self.getSibling("ArchitectureBuilder").props.snapEnabled=True

	elif event.label=='Hide Handles':
		self.getSibling("ArchitectureBuilder").props.hideHandles=True

	elif event.label=='Show Handles':
		self.getSibling("ArchitectureBuilder").props.hideHandles=False

	elif event.label=='Disable Interaction':
		self.getSibling("ArchitectureBuilder").props.enabled=False

	elif event.label=='Enable Interaction':
		self.getSibling("ArchitectureBuilder").props.enabled=True

	#----BOM Menu Items------------------------------------------------------------
	elif event.label=='Open BOM':
		system.perspective.navigate('/BOM',newTab=True)
	elif event.label=='Map':
		system.perspective.navigate('/Map',newTab=True)
	elif event.label=='JSON Structure':
		system.perspective.openDock("structure")
#		system.perspective.openPopup('JSON', 'Exchange/ArchitectureBuilder/StructureViewPrettyPrint', title='JSON Structure', resizable = True, modal=True, viewportBound=True, position = {'height': 'auto', 'width': '300px'} )
	elif event.label=='JSON Configs':
		system.perspective.openPopup('JSON', 'Exchange/ArchitectureBuilder/ConfigViewPrettyPrint', title='JSON Configs', resizable = True, modal=True, viewportBound=True, position = {'height': '50%', 'width': '300px'} )

customMethods.script:
paletteItem=self.props.paletteItems
self.view.custom.selectedPaletteItem=event
for index in range(len(paletteItem)):
	compareList= ["typeId", "id", "label", "category"]
	matchList=[]
	for c in compareList:
		matchList.append(paletteItem[index][c]==event[c])
	if all(matchList):
		self.view.custom.PaletteIndex=index
		break
